import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); PrintWriter out = new PrintWriter(System.out); int t = Integer.parseInt(br.readLine()); while (t-- > 0) { StringTokenizer st = new StringTokenizer(br.readLine()); int n = Integer.parseInt(st.nextToken()); int x = Integer.parseInt(st.nextToken()); if (x < n) { out.println("-1"); continue; } boolean found = false; for (int g = 1; g <= n; g++) { if (g == 1) { if (x == n) { for (int i = 1; i <= n; i++) out.print(i + (i == n ? "" : " ")); out.println(); found = true; break; } continue; } if ((x - n) % (g - 1) == 0) { int k = (x - n) / (g - 1); if (k >= 1 && k <= n / g) { int[] p = new int[n]; boolean[] used = new boolean[n + 1]; int idx = 0; for (int i = 1; i <= k; i++) { p[idx++] = i * g; used[i * g] = true; } for (int i = 1; i <= n; i++) { if (!used[i]) p[idx++] = i; } for (int i = 0; i < n; i++) out.print(p[i] + (i == n - 1 ? "" : " ")); out.println(); found = true; break; } } } if (!found) out.println("-1"); } out.flush(); out.close(); } }